DO $$ DECLARE     org_alpha UUID := 'a0000000-0000-0000-0000-000000000001';     org_beta  UUID := 'b0000000-0000-0000-0000-000000000002';     org_gamma UUID := 'c0000000-0000-0000-0000-000000000003';     org_delta UUID := 'd0000000-0000-0000-0000-000000000004';          cities TEXT[] := ARRAY['delhi', 'mumbai', 'bangalore', 'chennai'];     statuses TEXT[] := ARRAY['CONFIRMED', 'CANCELLED', 'PENDING'];          selected_org UUID;     selected_city TEXT;     selected_status TEXT;     selected_created_at TIMESTAMP;     selected_amount NUMERIC(12,2);          current_booking_id UUID;     i INT; BEGIN     FOR i IN 1..200 LOOP         selected_org := (ARRAY[org_alpha, org_beta, org_gamma, org_delta])[1 + (i \% 4)];                  IF i \% 2 = 0 THEN             selected_city := 'delhi';         ELSE             selected_city := cities[1 + (i \% 4)];         END IF;          selected_status := statuses[1 + (i \% 3)];                  IF i \% 3 = 0 THEN             selected_created_at := NOW() - ( (i \% 25) \vert{}\vert{} ' days' )::INTERVAL - ( (i \% 12) \vert{}\vert{} ' hours' )::INTERVAL;         ELSE             selected_created_at := NOW() - ( 31 + (i \% 55) \vert{}\vert{} ' days' )::INTERVAL;         END IF;          selected_amount := 1500.00 + ((i * 137) \% 8500);          INSERT INTO hotel_bookings (             org_id,             hotel_id,             city,             checkin_date,             checkout_date,             amount,             status,             created_at         ) VALUES (             selected_org,             'HOTEL-' \vert{}\vert{} ((i \% 15) + 101),             selected_city,             (selected_created_at + INTERVAL '5 days')::DATE,             (selected_created_at + INTERVAL '8 days')::DATE,             selected_amount,             selected_status,             selected_created_at         ) RETURNING id INTO current_booking_id;          IF i \% 2 = 0 THEN             INSERT INTO booking_events (booking_id, event_type, payload, created_at)             VALUES (                 current_booking_id,                 'BOOKING_INITIATED',                 json_build_object('gateway', 'stripe', 'retry_count', 0)::jsonb,                 selected_created_at             );              INSERT INTO booking_events (booking_id, event_type, payload, created_at)             VALUES (                 current_booking_id,                 'PAYMENT_' \vert{}\vert{} selected_status,                 json_build_object('amount', selected_amount, 'currency', 'INR')::jsonb,                 selected_created_at + INTERVAL '2 minutes'             );         END IF;     END LOOP; END $$;
